-- Secure, anonymous repair tracking for the optional storefront assistant.
-- The bearer token is generated by the client's Web Crypto API; only its hash
-- is persisted. Existing requests remain private and cannot be looked up.
ALTER TABLE public.solicitudes_reparacion
  ADD COLUMN IF NOT EXISTS tracking_token_hash TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS idx_solicitudes_reparacion_tracking_token_hash
  ON public.solicitudes_reparacion (tracking_token_hash)
  WHERE tracking_token_hash IS NOT NULL;

DROP FUNCTION IF EXISTS public.crear_solicitud_reparacion_publica(UUID, TEXT, TEXT, TEXT, TEXT, DATE, BOOLEAN, TEXT);

CREATE OR REPLACE FUNCTION public.crear_solicitud_reparacion_publica(
  p_request_key UUID,
  p_cliente_nombre TEXT,
  p_cliente_telefono TEXT,
  p_prenda TEXT,
  p_descripcion TEXT,
  p_fecha_deseada DATE,
  p_consent BOOLEAN,
  p_website TEXT DEFAULT '',
  p_tracking_token TEXT DEFAULT ''
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_nombre TEXT := NULLIF(BTRIM(p_cliente_nombre), '');
  v_telefono TEXT := regexp_replace(COALESCE(p_cliente_telefono, ''), '[^0-9]', '', 'g');
  v_prenda TEXT := NULLIF(BTRIM(p_prenda), '');
  v_descripcion TEXT := NULLIF(BTRIM(p_descripcion), '');
  v_payload JSONB;
  v_payload_hash TEXT;
  v_tracking_hash TEXT;
  v_existing_payload TEXT;
  v_existing_tracking_hash TEXT;
  v_request_id UUID;
  v_rate_count INTEGER;
BEGIN
  IF p_request_key IS NULL THEN
    RAISE EXCEPTION 'La clave de idempotencia es obligatoria';
  END IF;

  IF p_tracking_token IS NULL OR p_tracking_token !~ '^[A-Fa-f0-9]{64}$' THEN
    RAISE EXCEPTION 'El código de seguimiento no es válido';
  END IF;
  v_tracking_hash := encode(digest(lower(p_tracking_token), 'sha256'), 'hex');

  IF NULLIF(BTRIM(COALESCE(p_website, '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'No se pudo procesar la solicitud';
  END IF;

  IF v_nombre IS NULL OR LENGTH(v_nombre) < 2 OR LENGTH(v_nombre) > 100 THEN
    RAISE EXCEPTION 'Ingresa un nombre válido (2 a 100 caracteres)';
  END IF;
  IF LENGTH(v_telefono) < 8 OR LENGTH(v_telefono) > 15 THEN
    RAISE EXCEPTION 'Ingresa un teléfono válido';
  END IF;
  IF v_prenda IS NULL OR LENGTH(v_prenda) > 80 THEN
    RAISE EXCEPTION 'Indica qué prenda necesitas reparar';
  END IF;
  IF v_descripcion IS NULL OR LENGTH(v_descripcion) < 10 OR LENGTH(v_descripcion) > 1000 THEN
    RAISE EXCEPTION 'Describe el arreglo en 10 a 1000 caracteres';
  END IF;
  IF p_fecha_deseada IS NOT NULL AND p_fecha_deseada < CURRENT_DATE THEN
    RAISE EXCEPTION 'La fecha deseada no puede estar en el pasado';
  END IF;
  IF p_consent IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'Debes autorizar el uso de tus datos para gestionar esta solicitud';
  END IF;

  v_payload := jsonb_build_object(
    'nombre', v_nombre,
    'telefono', v_telefono,
    'prenda', v_prenda,
    'descripcion', v_descripcion,
    'fecha_deseada', p_fecha_deseada
  );
  v_payload_hash := encode(digest(v_payload::TEXT, 'sha256'), 'hex');

  SELECT id, idempotency_payload, tracking_token_hash
    INTO v_request_id, v_existing_payload, v_existing_tracking_hash
  FROM public.solicitudes_reparacion
  WHERE idempotency_key = p_request_key;

  IF FOUND THEN
    IF v_existing_payload IS DISTINCT FROM v_payload_hash THEN
      RAISE EXCEPTION 'La clave de idempotencia ya fue usada con otros datos';
    END IF;
    IF v_existing_tracking_hash IS DISTINCT FROM v_tracking_hash THEN
      RAISE EXCEPTION 'La clave de idempotencia ya fue usada con otro código de seguimiento';
    END IF;
    RETURN v_request_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('repair-request:' || v_telefono, 0));

  SELECT id, idempotency_payload, tracking_token_hash
    INTO v_request_id, v_existing_payload, v_existing_tracking_hash
  FROM public.solicitudes_reparacion
  WHERE idempotency_key = p_request_key;

  IF FOUND THEN
    IF v_existing_payload IS DISTINCT FROM v_payload_hash
      OR v_existing_tracking_hash IS DISTINCT FROM v_tracking_hash THEN
      RAISE EXCEPTION 'La clave de idempotencia ya fue usada con otros datos';
    END IF;
    RETURN v_request_id;
  END IF;

  SELECT COUNT(*) INTO v_rate_count
  FROM public.solicitudes_reparacion
  WHERE cliente_telefono = v_telefono
    AND created_at >= NOW() - INTERVAL '1 hour';
  IF v_rate_count >= 5 THEN
    RAISE EXCEPTION 'Se alcanzó el límite temporal de solicitudes para este teléfono';
  END IF;

  INSERT INTO public.solicitudes_reparacion (
    idempotency_key, idempotency_payload, tracking_token_hash,
    cliente_nombre, cliente_telefono, prenda, descripcion, fecha_deseada, consent_at
  )
  VALUES (
    p_request_key, v_payload_hash, v_tracking_hash,
    v_nombre, v_telefono, v_prenda, v_descripcion, p_fecha_deseada, NOW()
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_request_id;

  IF v_request_id IS NULL THEN
    SELECT id, idempotency_payload, tracking_token_hash
      INTO v_request_id, v_existing_payload, v_existing_tracking_hash
    FROM public.solicitudes_reparacion
    WHERE idempotency_key = p_request_key;
    IF NOT FOUND
      OR v_existing_payload IS DISTINCT FROM v_payload_hash
      OR v_existing_tracking_hash IS DISTINCT FROM v_tracking_hash THEN
      RAISE EXCEPTION 'La clave de idempotencia ya fue usada con otros datos';
    END IF;
  END IF;

  RETURN v_request_id;
END;
$$;

REVOKE ALL ON FUNCTION public.crear_solicitud_reparacion_publica(UUID, TEXT, TEXT, TEXT, TEXT, DATE, BOOLEAN, TEXT, TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.crear_solicitud_reparacion_publica(UUID, TEXT, TEXT, TEXT, TEXT, DATE, BOOLEAN, TEXT, TEXT)
  TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.consultar_estado_reparacion_publico(p_tracking_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF p_tracking_token IS NULL OR p_tracking_token !~ '^[A-Fa-f0-9]{64}$' THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'estado', estado,
    'updated_at', updated_at
  )
  INTO v_result
  FROM public.solicitudes_reparacion
  WHERE tracking_token_hash = encode(digest(lower(p_tracking_token), 'sha256'), 'hex');

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.consultar_estado_reparacion_publico(TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consultar_estado_reparacion_publico(TEXT) TO anon, authenticated;
